"""External English manuals and traceable literature catalog for Studio 0.6."""
import csv,json,sqlite3
from pathlib import Path
from docx import Document
from docx.shared import Inches,Pt,RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

OUT=Path('docs');SHOTS=Path('data/validation/english_ui');VERSION='0.6.0'
m=json.loads(Path('data/literature/reviewed_manifest.json').read_text(encoding='utf-8'))
extra=json.loads(Path('data/literature/six_oils_manifest.json').read_text(encoding='utf-8'));m['references'].update(extra['references']);m['profiles']+=extra['profiles']
extra=json.loads(Path('data/literature/comprehensive_manifest.json').read_text(encoding='utf-8'));m['references'].update(extra['references']);m['profiles']+=extra['profiles']
c=sqlite3.connect('data/nilephytodock.sqlite');c.row_factory=sqlite3.Row
ready=c.execute("SELECT count(*) FROM compound_structures WHERE status='ready'").fetchone()[0]
unique=c.execute("SELECT count(DISTINCT inchikey) FROM compound_structures WHERE status='ready'").fetchone()[0]
names=c.execute('SELECT count(*) FROM chemical_compounds').fetchone()[0]
from database.store import counts
n=counts(c);c.close()
def para(d,s):
 p=d.add_paragraph(s);p.paragraph_format.space_after=Pt(8);return p
def head(d,s):return d.add_heading(s,1)
def page(d,s):d.add_page_break();head(d,s)
def step(d,n,title,body):
 p=para(d,f'{n}  {title}');p.runs[0].bold=True;p.paragraph_format.keep_with_next=True;para(d,body)
def shot(d,name,caption):
 p=d.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.add_run().add_picture(str(SHOTS/(name+'.png')),width=Inches(6.55));p.paragraph_format.keep_with_next=True
 p=para(d,caption);p.alignment=WD_ALIGN_PARAGRAPH.CENTER
 for r in p.runs:r.font.size=Pt(10)
def code(d,s):
 p=para(d,s)
 for r in p.runs:r.font.name='Consolas';r.font.size=Pt(10)
def equation(d,label,num,den):
 p=d.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER;math=OxmlElement('m:oMath');r=OxmlElement('m:r');t=OxmlElement('m:t');t.text=label+' = ';r.append(t);math.append(r);f=OxmlElement('m:f')
 for tag,value in [('m:num',num),('m:den',den)]:
  a=OxmlElement(tag);r=OxmlElement('m:r');t=OxmlElement('m:t');t.text=value;r.append(t);a.append(r);f.append(a)
 math.append(f);p._p.append(math)
def book(title,intro):
 d=Document();s=d.sections[0];s.page_width=Inches(8.5);s.page_height=Inches(11);s.left_margin=s.right_margin=Inches(.85);s.top_margin=Inches(.68);s.bottom_margin=Inches(.65)
 for name,size in [('Normal',11.5),('Title',24),('Heading 1',17),('Heading 2',13)]:
  st=d.styles[name];st.font.name='Arial';st.font.size=Pt(size);st.font.color.rgb=RGBColor(0,0,0)
 d.styles['Normal'].paragraph_format.line_spacing=1.10
 d.core_properties.author='Ahmed G Soliman and Malak Taha';d.core_properties.last_modified_by='NilePhytoDock Studio '+VERSION;d.core_properties.title=title
 h=s.header.paragraphs[0];h.text='NilePhytoDock Studio '+VERSION;h.runs[0].font.size=Pt(9)
 f=s.footer.paragraphs[0];f.alignment=WD_ALIGN_PARAGRAPH.CENTER;f.add_run('NilePhytoDock Studio 0.6.0  |  ');e=OxmlElement('w:fldSimple');e.set(qn('w:instr'),'PAGE');f._p.append(e)
 d.add_paragraph(title,'Title');para(d,intro);return d

def user():
 d=book('NilePhytoDock User Guide','Use this guide to prepare a receptor, select documented botanical profiles, run local docking, inspect contacts and export a reproducible study. This English manual is supplied outside the application. Developed by Ahmed G Soliman and Malak Taha.')
 step(d,1,'Open the current release','Open NilePhytoDock Studio 0.6 from the desktop shortcut or run NilePhytoDock.exe in the Studio 0.6.0 portable folder. Keep the entire _internal folder beside the executable. P2Rank, Java and Smina run locally; an internet connection is optional for structure maintenance.')
 step(d,2,'Check the engines','Wait until the status reads Engines available. Settings lists the checks for P2Rank, Smina, RDKit and ProLIF. New studies and reports are stored in writable folders; the installation folder contains the read-only seed library.')
 shot(d,'overview','The English workspace displays actual library counts and local engine availability.')
 page(d,'Select the correct analytical profile')
 step(d,3,'Search the botanical library','Search by botanical name, compound, PMCID or source. Check the intended profiles in the list. Several cultivars, harvest months, plant parts and extraction methods may belong to the same species. Hover over a profile to read its origin and source notes.')
 para(d,f"The release contains {n['botanical_oils']} distinct botanical oils ({n['essential_oils']} essential and {n['fixed_oils']} fixed), {n['profiles']} analytical profiles across {n['species']} botanical taxa and {names} normalized compound-name records. {ready} records are ready for local docking, representing {unique} distinct verified InChIKeys. The remaining {names-ready} names need identity or stereochemical review. Names and measured observations are not counts of unique structures.")
 para(d,'The new literature pack contains 90 literature profiles and 1448 observations from 37 primary PMC papers. Sample geography is explicit; an Egyptian author or seller does not establish Egyptian cultivation. Olive, grape and hibiscus profiles are included with explicit geographic uncertainty because the selected analytical papers do not establish their growing location. The external Literature_Catalog_EN.csv lists every sample and source.')
 para(d,'Read Reported Value together with Reported Unit. Essential-oil GC peak-area percentages can support an abundance-weighted oil index. HPLC concentrations in ug/g or ug/mL retain those units. Headspace, qualitative LC-MS annotations, separated lipid fractions and fatty-acid pools have no oil index. Only source-eligible, resolved small molecules can be docked individually. Analytical fatty-acid pools and unresolved sum lipid species are blocked.')
 para(d,'Unknown peaks, class totals, oil yield and retention indices are not treated as compounds. Trace means detected without a reported numerical abundance; it does not mean zero. Missing or non-detected cells are not given invented values.')
 shot(d,'library_hplc','Turmeric concentrations remain HPLC solution concentrations rather than oil percentages.')
 page(d,'Prepare and inspect the receptor')
 step(d,4,'Import a structure','Open Protein targets and import one or several PDB or mmCIF files. Inspect the structure, chains, missing residues, ligands, waters, cofactors and metals before continuing. The original file is copied unchanged into the study.')
 step(d,5,'Choose receptor preparation','In Screening setup, open Receptor preparation. Set the general protonation pH and water handling. Enter only the bound residues that should be removed. Use the residue identifier shown by structure inspection. For the supplied 3PTB validation fixture, BEN A:1 removes the crystallographic benzamidine ligand; this is an example, not a universal setting.')
 para(d,'The preparation pipeline does not rebuild missing loops or side chains and does not calculate a binding-site-specific pKa model. Decide which cofactors and metals to retain for the actual biological question. A successful preparation log does not establish that the chosen receptor state is biologically appropriate.')
 step(d,6,'Predict the binding sites','Choose Prepare and predict all. P2Rank runs on each prepared receptor and saves its pocket predictions. In Binding sites, select each target and review the pocket residues, center, dimensions and 3D location. Select the intended pocket for every receptor.')
 step(d,7,'Confirm the automatic transfer','Return to the Binding site tab in Screening setup. The selected target pocket automatically populates the center and box dimensions. Automatic mode keeps these fields read-only. Custom box mode permits explicit manual coordinates. Check that the box covers the intended site before starting.')
 page(d,'Configure and run the screening')
 step(d,8,'Set the protocol','In Docking protocol, choose exhaustiveness, pose count, CPU threads, scoring function and random seed. Keep a recorded seed and protocol for comparisons. Increasing exhaustiveness increases search effort and runtime; it does not by itself validate a docking model.')
 step(d,9,'Choose the results folder','Use Output to select a writable folder with enough free space. Each study creates separate protein, pocket, docking, interaction, figure, ranking and report outputs. Prefer a new study folder for a new scientific comparison.')
 step(d,10,'Start and monitor','Run screening becomes available when engines, targets, profiles and binding-site settings are ready. Enter a clear study name in Screening setup before starting. Watch the progress and logs. Pause waits at a safe calculation checkpoint; Cancel records the interrupted state. Wait for completion before interpreting the final ranking.')
 shot(d,'protocol','The protocol tab reuses the actual controls that determine the Smina command.')
 para(d,'Only identity-verified and locally prepared structures are submitted. Concentration-based profiles can submit positive reported constituents; qualitative profiles can submit reported presence. An unresolved identity is skipped rather than replaced with a guessed structure.')
 page(d,'Inspect results and profile priorities')
 step(d,11,'Review completed poses','Docking results shows the receptor, compound, pocket, pose rank, Smina score and calculation status. Double-click a calculated pose to open Interactions. Compare poses in the same validated protocol and inspect the actual geometry.')
 step(d,12,'Inspect molecular contacts','Review the ligand pose in the 3D receptor view and the accompanying 2D contact diagram. Toggle distance, interaction-type and residue labels as needed. Contacts come from ProLIF and RDKit; they are not independent experimental binding evidence.')
 shot(d,'interactions','The contact view uses a real saved pose and calculated contacts.')
 step(d,13,'Read priorities with coverage','The profile index weights within-target docking percentiles by reported essential-oil GC peak area over successfully screened constituents. Read screened coverage and source warnings with the index. A duplicate compound entry in a profile blocks its oil index until curated. HPLC, headspace and fatty-acid pool profiles display no oil index.')
 para(d,'The index is a screening prioritization proxy. It does not predict mixture synergy, potency, exposure, efficacy or safety. Incomplete major-component tables remain incomplete; no percentage is rescaled to make the original source add to 100%.')
 page(d,'2D and 3D visualization controls')
 para(d,'Choose Classic for ordered contacts, Circular for a central ligand surrounded by residues, or Functional group for source-atom features linked to actual residues. Reset Layout fits the deterministic map. Change 2D Line Colors customizes a category without changing residue fills. Residue fills can show polarity, charge, biochemical class, amino-acid identity, hydrophobicity, aromaticity or interaction participation. These fills are independent of interaction-line colors. The segmented participation ring retains every category associated with a residue.')
 para(d,'Blue dashed = hydrogen bond; green dotted = hydrophobic; orange = ionic; purple = pi-pi; magenta = pi-cation; gray = van der Waals; gold = metal coordination. One minimum-distance link per residue/type reduces clutter; parentheses count all contacts. SVG tooltips and the contact table retain the individual atom pairs. Diagram lengths are schematic; labels report measured 3D distances.')
 para(d,'The 3D toolbar provides Cartoon, Ribbon, Backbone, Sticks, Ball and Stick, Lines, Surface, Transparent Surface and Molecular Spheres. Protein colors include chain, secondary structure, residue identity, polarity, charge, hydrophobicity, interaction participation and B factor. Structural confidence is available only after explicit confirmation that the B column contains pLDDT.')
 para(d,'Appearance presets and rendering offers Scientific Classic, High Contrast and Publication Quality. Background, protein and surface opacity, ligand carbon and optional protein color, label size, material, ambient occlusion and fog are explicit controls. Highlight Binding Residues preserves the chosen opacity. Expand Residues interactions and surfaces to choose labels, filter contacts, show the binding site, pocket residues or surfaces, and toggle hydrogens. Contact-endpoint hydrogens retain their chemical bonds; aromatic links terminate at actual ring centroids. Click a contact-table row to focus its actual residue and recorded geometry.')
 para(d,'Export 2D figures as SVG and 300/600-DPI PNG. Export 3D PNG at 2400 by 1800 pixels (300 DPI) or 4800 by 3600 (600 DPI). Complex PDB, saved ligand SDF and a PyMOL PML script are available. PSE session export is enabled only when a legitimate PyMOL installation is available.')
 page(d,'Scientific charts and bubble plots')
 para(d,'Charts has a resizable filter panel, scientific canvas and point-details panel. Select a supported chart, target, source profile, interaction category and top-compound limit. Hover for recorded values; click for details. Scroll or drag to zoom and pan. Unsupported chart types are disabled when their required data are absent.')
 para(d,'Available chart types: docking heatmap; compound-protein bubble plot; oil-protein bubble plot; oil ranking; compound ranking; interaction matrix; interaction network; residue frequency; compound-oil relationship network; multitarget comparison; interaction-frequency heatmap; functional-group frequency and residue network; molecular and interaction-fingerprint similarity heatmaps; and chemical diversity. They use saved calculations, not illustrative scores.')
 para(d,'Compound bubbles preserve each source profile separately, including compounds reported in several oils. Color and marker identify the oil. Area is uniform or proportional to original GC peak area on a common scale across oils. HPLC concentrations never become GC percentages. Oil bubbles use normalized screening index or screened GC peak area. Tooltips retain the original measurement units.')
 para(d,'Interaction matrices retain multiple interaction types per cell. Network edges distinguish classified contacts from source membership. Export PNG, SVG, PDF, CSV, XLSX and the plotted specification JSON to preserve both the figure and its underlying records.')
 page(d,'Functional groups similarity and historical evidence')
 step(d,14,'Analyze the saved site','Open Molecular analysis, select a protein and binding site, then Analyze saved poses. Inspect group-residue associations, presence versus direct participation, structural clusters and exploratory enrichment. Export analysis tables to preserve full values.')
 para(d,'SMARTS identifies chemical groups from the saved molecular graph and source atom indices. A group present in a ligand is not automatically participating. Conventional groups and overlapping aromatic or hydrophobic features are separate domains. Event counts, unique structures and ligand-residue pairs have different meanings.')
 para(d,'Chemical similarity uses chirality-aware Morgan fingerprints and Tanimoto, independent of docking scores. Interaction similarity compares binary residue/category fingerprints only within one prepared receptor and pocket. Small or structurally redundant cohorts receive no enrichment claim. The complete similarity matrices accompany approximate diversity plots.')
 step(d,15,'Export actual interactions','In Interactions choose Export Interaction Table, then complete, best pose, selected protein, selected compound, functional-group summary or frequency summary. Nonempty calculated results export as CSV, XLSX and DOCX with identities, atom indices, measured geometry and method.')
 para(d,'In Botanical library use Preparation / heritage to distinguish Essential Oils, Fixed Oils, Botanical Extracts, Resins and Aromatic Preparations and Individual Natural Compounds. Ancient Egyptian Botanical Heritage lists 12 evidence-qualified candidates with period, source, confidence and taxonomic limits. An ancient genus-level residue cannot identify the species used in a modern oil study.')
 page(d,'Export reopen and troubleshoot')
 step(d,16,'Export the study','Open Reports to generate the scientific report and tabular exports. The study folder includes reproducibility metadata, CSV/XLSX tables, figures, process logs, actual pocket boxes and a project database snapshot. Preserve the complete folder when sharing a calculation.')
 step(d,17,'Reopen a saved project','Use Open saved project to select the saved project database. Confirm that the expected source structures, prepared receptors and pose files are available. Keep the study outputs together when relocating them.')
 step(d,18,'Find the external documentation','Documentation beside the executable contains this guide, Build_and_Methods_EN.pdf, the literature catalog and composition observations. No guide is embedded in the application interface. The source ZIP contains scripts, reviewed table transcriptions, source links and hashes used to build this release.')
 para(d,'If the old version or icon appears, open the Studio 0.6 shortcut and check the window version. If an engine fails, inspect Settings and the execution logs. If no ligands run, check structure status and the selected analytical profile. If automatic mode is unavailable, predict and select pockets for every target. If an index is blank, read the profile type, coverage and source-review warning.')
 para(d,'For online structure maintenance, the application queries PubChem and validates exact normalized synonyms, molecular connectivity and stereochemistry conservatively. Keep a backup before maintaining a curated library. Manual repair of ambiguous names and unsupported stereoisomers requires scientific review.')
 para(d,'Release validation covers the current Windows 11 host. Windows 10 and a clean virtual machine have not been tested. The executable is unsigned. The supplied BEN/3PTB redocking benchmark is one validation system and does not establish general docking accuracy.')
 clean_borders(d);d.save(OUT/'User_Guide_EN.docx')

def methods():
 d=book('NilePhytoDock Build and Scientific Methods','This document explains how Studio 0.6.0 was implemented, how literature data become traceable compound records, and how the local screening pipeline produces results. It is intended for users and developers who need to audit or reproduce the software. Developed by Ahmed G Soliman and Malak Taha.')
 head(d,'Implementation and dependencies')
 para(d,'The application is a native Python desktop program built with PySide6 6.12.0 and packaged with PyInstaller. UpgradeMixin supplies the minimalist dashboard, interaction controls and chart workspace. StudioMixin supplies navigation, theme and grouped protocol controls. RedesignMixin connects pocket selection and live workflow state to BaseWindow. These layers reuse the scientific backend rather than replacing it with simulated output.')
 para(d,'P2Rank 2.5.1 predicts receptor pockets using bundled Temurin Java 17.0.19. Native Smina 2020.12.10 performs docking. RDKit 2026.09.1 supplies chemical validation, conformers and descriptors; Meeko writes ligand PDBQT. ProLIF 2.2.3, RDKit and MDAnalysis classify contacts. OpenBabel and protein utilities prepare receptor coordinates. PLIP is not used.')
 para(d,'Key modules are app/gui.py, app/redesign.py and app/studio.py for the UI; database/store.py and import_literature.py for schema and safe imports; scientific/ligands.py, proteins.py, pockets.py, docking.py, pipeline.py and ranking.py for calculations; visualization for the 3D view and 2D diagrams; reporting and scientific/project_outputs.py for reproducible exports.')
 para(d,'The seed database contains source data and prepared ligand metadata with no demonstration projects or docking scores. A per-user writable copy stores studies. The new literature manifest merges into an existing installation without replacing its projects or original composition observations.')
 page(d,'Literature acquisition and data model')
 para(d,'Primary research was located on NCBI PubMed Central. The open-access full-text JATS was downloaded through the Europe PMC fullTextXML endpoint and cached unchanged with SHA-256 hashes. tools/research_ncbi.py records article identifiers, title, DOI, license, table rows and sample-collection methods. tools/build_literature_manifest.py and the subsequent reviewed pack builders apply explicit reviewed table and sample-column mappings; it does not scrape guessed percentages from abstracts.')
 para(d,'Three reviewed manifests add 90 analytical profiles and 1448 observations from 37 primary papers. They preserve the previous 661 composition observations. The final database has 57 distinct botanical oils (46 essential and 11 fixed), 68 taxa, 119 profiles, 819 normalized names and 2109 source observations. Egyptian collections, market samples and non-Egyptian reference samples retain their distinct geographic evidence.')
 para(d,'Every imported observation retains the original name, raw table row, table identifier, row number, measured value, unit, transcribed uncertainty or an explicitly labelled mean-only subset, annotation level and reference. Separate profiles preserve harvest month, cultivar, plant part, preparation and analytical technique. GC peak area, HPLC concentration, qualitative presence and separated lipid-fraction measurements remain distinct.')
 para(d,'Oil yield, retention time, retention index, unknown peaks and class totals are not molecular constituents. Incomplete major-component tables are labelled as subsets. No missing values are set to zero, no profiles are merged by botanical name, and no original percentages are normalized to 100%. Fixed-oil fatty-acid pools do not imply that free fatty acids were the native molecular species.')
 para(d,'The blue-lily paper PMC12717157 was excluded because its Methods names N. nucifera while the title and table name Nymphaea nouchali var. caerulea. The white Egyptian water lily Nymphaea alba is included with its actual evidence. The Egyptian olive-cultivar study PMC12869296 confirms local collection, but its LC-MS annotation table is available only on request; those LC-MS observations were not invented.')
 page(d,'Compound identity and ligand preparation')
 para(d,'Published annotation and structure verification are separate fields. A GC-MS library match or tentative LC-MS assignment is not independent proof of a molecular identity. Specific derivatives, unspecified glycosides and unclear stereoisomers remain visible for review. The source text survives any conservative name correction.')
 para(d,'For structure maintenance, scientific/ligands.py queries PubChem PUG REST by name, caches the response and synonyms, and requires an exact normalized synonym match. RDKit must accept the returned SMILES and a single molecular component. The current policy rejects unresolved stereocenters and candidates whose source name does not establish a necessary stereochemical assignment. Matching InChIKeys can reuse prepared structures while retaining distinct source names.')
 para(d,f'The final library has {ready} prepared records representing {unique} distinct InChIKeys; {names-ready} names remain under review. This release does not contain 1000 unique verified structures. It meets the botanical breadth target using documented studies rather than padding the count with repeated peaks or unsupported structures.')
 para(d,'Accepted ligands receive hydrogens, an ETKDGv3 conformer with seed 20261029, then MMFF94s minimization when fully parameterized, otherwise UFF. The minimizer must converge. Meeko generates PDBQT. Prepared SDF, PDBQT, molecular properties, PubChem CID, source URL, retrieval time and preparation notes are stored. Bundled file paths are relative so the portable directory can move.')
 para(d,'The current pipeline prepares one conformer per accepted record. It does not enumerate a pH-dependent ligand ensemble or infer missing source stereochemistry. Docking a structure does not upgrade a tentative analytical observation into a confirmed constituent.')
 page(d,'Receptor pocket docking and contacts')
 para(d,'Original receptor files are copied unchanged. Preparation records the selected chains, water handling, bound-residue removals and a general pH model. It does not rebuild missing loops or side chains. The chosen receptor state, cofactors, metals and protonation require scientific judgment.')
 para(d,'P2Rank runs on prepared coordinates. Its pocket center and residue coordinates define the selected site. Geometric box dimensions cover the pocket residue extent with a configurable margin; custom mode records the supplied box explicitly. The UI displays the selected per-target center and dimensions, and the same values are passed to Smina. Actual commands, settings and engine version are saved.')
 para(d,'Smina searches the receptor box using the chosen scoring function, exhaustiveness, pose count, CPU count and seed. Cache keys include the relevant structure and protocol information; cached pose files are checked. Failed jobs and contact/figure review states are recorded rather than replaced with synthetic scores. Cancellation preserves completed calculations and the interrupted status.')
 para(d,'ProLIF and RDKit classify pose contacts using chemical features and geometry. The implementation records residue and atom identifiers, interaction type, distance, angle where relevant and method metadata. Metal/contact filtering avoids indiscriminate nearest-atom interaction claims. The 2D diagram lays out actual ligand and residue contacts, and the 3D viewer displays saved coordinates.')
 para(d,'Reports contain the actual docking results, profile priorities, interaction tables, figures, provenance JSON and project snapshot. Reopening a saved project reads stored results rather than rerunning or fabricating calculations.')
 page(d,'Geometry validation and visualization semantics')
 para(d,'Every contact stores atom indices, residue name, chain, sequence number, insertion code, feature anchors and geometry version. Hydrogen-bond distances join donor and acceptor heavy atoms; their donor-H-acceptor angle is independently recomputed. Aromatic contacts use ring centroids and validated plane geometry. Conservative metal classification requires a complete chemically plausible Zn or Mg coordination shell.')
 para(d,'Before display, saved receptor and ligand coordinates are compared with interaction metadata. The browser independently checks parsed atoms and feature endpoints against that payload. A mismatch raises an error. Reanalysis archives previous contact records before replacement, and original docking scores and poses survive.')
 para(d,'A native WebGL audit verified 222 contacts in six real poses across 3PTB and 1IEP, including three ring-feature contacts. Corrupted distances and coordinates were rejected. Three 2D styles and seven residue modes were checked for every pose. Nine protein representations, eight color modes, three ligand styles, three appearance presets and the pLDDT confirmation gate were exercised.')
 para(d,'Formula checks compare each of the 186 ready records against authoritative PubChem CID formulas. They establish consistency of the resolved structure, not confirmation of the analytical peak. A stricter source-geometric-identity audit withdrew 17 automated approvals with unresolved E/Z assignments. Candidate structures and prior preparation files remain available for review; they do not contribute to the ready counter or new docking.')
 para(d,'The six requested oils were reviewed individually. Marjoram, basil, fennel, cumin and peppermint were added; Egyptian thyme was already present. Peppermint is an explicitly Moroccan reference. Cumin is an Egyptian market sample without a documented growing site. The peppermint methyl acetate peak at RI 1295 is retained but excluded pending source-identity review. Published individual rows sum to 99.52 percent while the printed total is 99.51; no row was altered to force agreement.')
 page(d,'Priority calculation and validation scope')
 para(d,'For each receptor, the best available Smina energy for each successful compound is ranked with average ranks for ties. Lower energy receives the higher percentile. A singleton receives 0.5. Identical InChIKeys form one percentile population entry. The percentile is relative to the set screened in that study, so it is not an absolute potency scale.')
 equation(d,'Compound percentile','N minus average energy rank','N minus 1')
 para(d,'The essential-oil priority averages these percentiles using the original reported positive GC peak-area percentages among successfully screened constituents. Coverage is the sum of screened original peak areas, and the fraction of the reported composition is also retained. Coverage below 70% is flagged. Duplicate compound entries suppress the affected profile index rather than double-weighting it.')
 equation(d,'Oil priority','sum of original peak area times compound percentile','sum of successfully screened original peak areas')
 para(d,'HPLC concentrations, qualitative LC-MS annotations, headspace and fatty-acid pools have no oil index. Their individual docking scores remain available. Multitarget weighting does not silently renormalize away a missing positive-weight target. A deterministic one-at-a-time plus or minus 10% abundance perturbation reports sensitivity.')
 para(d,'The current automated suite checks 56 cases, including source hashes and raw rows, source preservation, repeat-import behavior, numeric transcriptions, unit separation, ranking exclusions and the English GUI. Installation verification performs real docking of the three control-turmeric constituents against prepared 3PTB after removing BEN A:1, checks the Smina box against the saved pocket, and verifies that HPLC measurements receive no oil index.')
 para(d,'The earlier independent benzamidine/3PTB benchmark gave approximately 0.394 angstrom heavy-atom RMSD for its top pose without post-alignment. This single system does not establish broad predictive accuracy. Native Windows 11 is tested; Windows 10, a clean VM and every GPU/display configuration are not. The executable is unsigned.')
 page(d,'Rebuild and maintain the release')
 para(d,'Use the locked requirements and preserve the bundled third-party notices. The exact Smina binary is an upstream native build, not a locally rebuilt engine. Source modules, reviewed source mappings, source hashes and validation evidence are supplied in the source ZIP.')
 code(d,'python -m pytest -q\npython -m PyInstaller --noconfirm --distpath dist_comprehensive --workpath build/pyinstaller_comprehensive build/NilePhytoDock.spec')
 para(d,'The manifest importer must first be applied to a seed built from the original source documents and reviewed CSV. It records a manifest hash and is idempotent. A changed manifest requires an explicit reviewed migration, not an overwrite of an already imported sample. Structure preparation requires the generated import summary listing new compound identifiers. Do not rerun a name import against the same data under a different hash without reviewing the change.')
 para(d,'For an explicit installation check, use a fresh writable output folder and a private NILEPHYTODOCK_DATA environment directory. Run the following command with the supplied 3PTB fixture. It performs real calculations, writes verification.json and exits; it is never invoked during normal startup.')
 code(d,'NilePhytoDock.exe --verify-installation C:/Validation/NewCheck C:/Source/tests/fixtures/3PTB.pdb')
 para(d,'The executable embeds the supplied logo as a seven-size ICO. The shortcut uses an explicit icon path, and the process sets a Windows AppUserModelID. The application locale is English with left-to-right layout. Documentation is copied beside the portable directory after building; the PyInstaller specification does not embed the manuals.')
 para(d,'Maintain a backup of the per-user database and the complete study directory. Review identity changes, taxonomic mappings, new measurement units and source corrections before enabling additional molecules. The external catalog lists sample geography and completeness; the observation CSV supplies table/row provenance. Kew POWO supports the Mentha viridis to M. spicata and Rosa polyantha to R. multiflora synonym mappings; the original published labels are retained.')
 page(d,'Functional group and similarity methods')
 para(d,'Versioned atom-centred SMARTS assigns functional centres with specificity precedence: ester is not ether, amide is not amine, and phenolic hydroxyl is not also alcohol. Aromatic rings, alkenes and ProLIF hydrophobic atom features are orthogonal domains. Explicit hydrogen contacts map to their bonded heavy atom for group attribution. Each assignment retains source SDF indices.')
 para(d,'Only atoms or ring features involved in a verified ProLIF contact establish direct participation. Summary tables distinguish present groups, actual contact events, distinct InChIKeys and distinct ligand-residue pairs. They describe predicted associations and cannot establish that a group caused affinity.')
 para(d,'Structural similarity uses Morgan radius 2, 2048 bits, chirality enabled, and Tanimoto. Butina clustering uses a 0.65 similarity threshold. Interaction fingerprints encode chain, residue number, insertion code and interaction category; Jaccard is evaluated separately for each receptor/pocket cohort. Empty-empty fingerprints are unavailable. Classical MDS visualizes 1 minus structural similarity without using docking energies; omitted negative eigenvalues make the 2D view approximate.')
 para(d,'Exploratory enrichment requires at least 12 structural-cluster representatives, chosen lexicographically by InChIKey independently of score. Repeated nonempty Murcko scaffolds are also pruned; acyclic molecules use fingerprint clusters. Top and bottom score quartiles include ties; overlapping cutoffs suppress testing. Two-sided Fisher tests receive Benjamini-Hochberg correction over tested groups. Small cohorts and withheld analyses are reported explicitly. This is not experimental activity validation.')
 para(d,'The separate NilePhytoDock Case Study reports actual P2Rank localization, Smina screening and benchmark RMSD in the original docking frame. Its machine-readable evidence includes commands, raw poses, contact atom mappings, coverage, source membership, functional groups and both similarity matrices.')
 refs=list(m['references'].items())
 for index in range(0,len(refs),6):
  page(d,'Primary literature sources'+(' continued' if index else ''))
  for pmc,r in refs[index:index+6]:
   p=para(d,pmc+'  '+r['title']);p.runs[0].bold=True;p.paragraph_format.keep_with_next=True
   para(d,'DOI '+r['doi']+'\n'+r['url'])
  if index:
   para(d,'Taxonomic mapping sources\nhttps://powo.science.kew.org/taxon/30281957-2\nhttps://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:733725-1')
 clean_borders(d);d.save(OUT/'Build_and_Methods_EN.docx')

def catalog():
 with (OUT/'Literature_Catalog_EN.csv').open('w',encoding='utf-8-sig',newline='') as f:
  fields=['species','label','type','part','method','origin','geography_status','basis','rankable','observations','pmcid','table_id','doi','source_url','notes'];w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
  for p in m['profiles']:w.writerow({**{k:p[k] for k in fields if k in p},'observations':len(p['observations']),'doi':m['references'][p['pmcid']]['doi'],'source_url':m['references'][p['pmcid']]['url']})
 with (OUT/'Literature_Observations_EN.csv').open('w',encoding='utf-8-sig',newline='') as f:
  w=csv.writer(f);w.writerow(['Species','Profile','Compound as published','Normalized input name','Reported value','Reported unit','SD','Value status','Annotation level','PMCID','Table','Row','Source URL'])
  for p in m['profiles']:
   for o in p['observations']:w.writerow([p['species'],p['label'],o['original_name'],o['name'],o['value'],o['unit'],o['sd'],o['status'],o['annotation'],p['pmcid'],p['table_id'],o['source_row'],m['references'][p['pmcid']]['url']])

def clean_borders(d):
 for e in list(d._element.iter(qn('w:pBdr'))):e.getparent().remove(e)
 for style in d.styles:
  for e in list(style._element.iter(qn('w:pBdr'))):e.getparent().remove(e)

if __name__=='__main__':user();methods();catalog();print('Two English manuals and external literature catalog written')
